import random, itertools, time
n=16
edges=list(itertools.combinations(range(n),2))

def girth_ok(E):
    adj=[set() for _ in range(n)]
    for u,v in E:
        adj[u].add(v); adj[v].add(u)
    # check cycles length <8 by BFS from each edge removing it path <=6
    for u,v in E:
        adj[u].remove(v); adj[v].remove(u)
        # BFS from u to v up to depth6
        seen={u}; frontier=[u]
        ok=True
        for d in range(1,7):
            nf=[]
            for x in frontier:
                for y in adj[x]:
                    if y==v:
                        ok=False; break
                    if y not in seen:
                        seen.add(y); nf.append(y)
                if not ok: break
            if not ok: break
            frontier=nf
        adj[u].add(v); adj[v].add(u)
        if not ok: return False
    return True

def add_ok(adj,u,v):
    # can add if no path u-v length <=6
    seen={u}; frontier=[u]
    for d in range(1,7):
        nf=[]
        for x in frontier:
            for y in adj[x]:
                if y==v:
                    return False
                if y not in seen:
                    seen.add(y); nf.append(y)
        frontier=nf
    return True

def is_3_col(E):
    adj=[set() for _ in range(n)]
    for u,v in E: adj[u].add(v); adj[v].add(u)
    colors=[-1]*n
    order=sorted(range(n), key=lambda x: -len(adj[x]))
    def bt(i):
        if i==n: return True, colors[:]
        v=order[i]
        used={colors[w] for w in adj[v] if colors[w]!=-1}
        for c in range(3):
            if c not in used:
                colors[v]=c
                ok,sol=bt(i+1)
                if ok: return True,sol
                colors[v]=-1
        return False,None
    return bt(0)

