def mval(m,x):
    y=m[x]
    if y is None:
        return False
    return is_true(y)

def get_edges(m):
    return [Elist[i] for i,x in enumerate(e) if mval(m,x)]

def short_cycles(edges, maxlen=7):
    adj=[set() for _ in range(n)]
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    cycles=set()
    def norm(cyc):
        k=len(cyc); best=None
        for arr in (cyc, list(reversed(cyc))):
            for i in range(k):
                r=tuple(arr[i:]+arr[:i])
                if best is None or r<best: best=r
        return best
    for start in range(n):
        stack=[(start,[start])]
        while stack:
            v,path=stack.pop()
            if len(path)>maxlen: continue
            for w in adj[v]:
                if w==start and len(path)>=3:
                    cycles.add(norm(path[:]))
                elif w>start and w not in path and len(path)<maxlen:
                    stack.append((w,path+[w]))
    return [list(c) for c in cycles]

